/**
 * Token usage of one chat session, as shown in the persistent status bar.
 * Reported upward by <Chat> (like loading/title) so the shell can display it
 * for whichever run is active, independent of the chat's own context gauge.
 */
export interface SessionUsage {
  /** Current context-window occupancy (latest turn's prompt tokens). */
  contextTokens: number;
  /** Model context window in tokens; 0 when unknown. */
  contextWindow: number;
  /** Tokens sent to the model, summed over the session's turns. */
  promptTokens: number;
  /** Tokens generated by the model, summed over the session's turns. */
  completionTokens: number;
  totalTokens: number;
  cost?: number;
  cacheReadTokens?: number;
  cacheWriteTokens?: number;
  /** True when contextTokens is a transcript estimate, not provider-reported. */
  estimated?: boolean;
}

export interface SessionUsageDisplay {
  /** Context chip, e.g. "ctx 38.2k/200k · 19%" (just "ctx 38.2k" if no window). */
  context: string;
  /** Session totals chip, e.g. "↑120k ↓8.4k · $0.42"; empty when nothing summed. */
  totals: string;
  /** Multi-line tooltip with the exact numbers. */
  title: string;
  /** Context fill 0–100, or null when the window is unknown. */
  percent: number | null;
  /** True when the context is nearly full (≥ 80%). */
  warn: boolean;
}

export function formatTokens(n: number): string {
  if (n >= 1_000_000) {
    const v = (n / 1_000_000).toFixed(1);
    return `${v.endsWith(".0") ? v.slice(0, -2) : v}M`;
  }
  if (n >= 1000) {
    const v = (n / 1000).toFixed(1);
    return `${v.endsWith(".0") ? v.slice(0, -2) : v}k`;
  }
  return String(Math.round(n));
}

function formatCost(cost: number): string {
  return cost > 0 && cost < 0.01 ? "<$0.01" : `$${cost.toFixed(2)}`;
}

/** Null when there is nothing worth showing (no context and no totals). */
export function formatSessionUsage(
  usage: SessionUsage | null | undefined,
): SessionUsageDisplay | null {
  if (!usage) return null;
  const hasContext = usage.contextTokens > 0;
  const hasTotals = usage.promptTokens > 0 || usage.completionTokens > 0;
  if (!hasContext && !hasTotals) return null;

  const percent =
    hasContext && usage.contextWindow > 0
      ? Math.min(
          100,
          Math.round((usage.contextTokens / usage.contextWindow) * 100),
        )
      : null;

  const approx = usage.estimated ? "~" : "";
  let context = "";
  if (hasContext) {
    context =
      usage.contextWindow > 0
        ? `ctx ${approx}${formatTokens(usage.contextTokens)}/${formatTokens(usage.contextWindow)} · ${approx}${percent}%`
        : `ctx ${approx}${formatTokens(usage.contextTokens)}`;
  }

  const totalsParts: string[] = [];
  if (hasTotals) {
    totalsParts.push(
      `↑${formatTokens(usage.promptTokens)} ↓${formatTokens(usage.completionTokens)}`,
    );
  }
  if (usage.cost !== undefined && usage.cost > 0) {
    totalsParts.push(formatCost(usage.cost));
  }

  const lines: string[] = [];
  if (hasContext) {
    lines.push(
      usage.contextWindow > 0
        ? `Context: ${usage.contextTokens.toLocaleString("en-US")} of ${usage.contextWindow.toLocaleString("en-US")} tokens (${percent}%)`
        : `Context: ${usage.contextTokens.toLocaleString("en-US")} tokens (window unknown)`,
    );
  }
  if (hasTotals) {
    lines.push(
      `Session: ${usage.promptTokens.toLocaleString("en-US")} in, ${usage.completionTokens.toLocaleString("en-US")} out, ${usage.totalTokens.toLocaleString("en-US")} total`,
    );
  }
  if (usage.estimated) {
    lines.push("Context is estimated from the transcript (≈ chars ÷ 4).");
  }
  if (usage.cacheReadTokens !== undefined) {
    lines.push(`Cache read: ${usage.cacheReadTokens.toLocaleString("en-US")}`);
  }
  if (usage.cacheWriteTokens !== undefined) {
    lines.push(
      `Cache write: ${usage.cacheWriteTokens.toLocaleString("en-US")}`,
    );
  }
  if (usage.cost !== undefined && usage.cost > 0) {
    lines.push(`Cost: ${formatCost(usage.cost)}`);
  }

  return {
    context,
    totals: totalsParts.join(" · "),
    title: lines.join("\n"),
    percent,
    // Unrounded ratio: 79.5% must not read as "nearly full" because it rounds up.
    warn:
      usage.contextWindow > 0 &&
      usage.contextTokens / usage.contextWindow >= 0.8,
  };
}
